1	use std::collections::HashSet;
2	use std::ffi::OsStr;
3	use std::ffi::OsString;
4	
5	use clap::Id;
6	use clap_lex::OsStrExt as _;
7	
8	use super::ArgValueCandidates;
9	use super::ArgValueCompleter;
10	use super::CompletionCandidate;
11	use super::SubcommandCandidates;
12	use super::ValueCandidates;
13	use super::custom::complete_path;
14	use super::custom::possible_value_candidates;
