16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Text of the value terminator carried by the option whose terminator was
47	    // consumed as the previous closed word. It only lives for one word: a second
48	    // terminator is a duplicate (and therefore illegal) while any other word
49	    // resumes normal parsing.
50	    let mut last_terminator: Option<OsString> = None;
51	    // Set when an already closed word carried a value that cannot be part of
52	    // the command line (a delimiter-separated value set that is overfull, has
53	    // an empty segment, ...). Completion then reports "no completion generated"
54	    // instead of guessing at unrelated candidates.
55	    let mut is_illegal = false;
56	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
57	    // conflicting candidates. Only recognized option names are recorded;
58	    // values, positionals, `--`-escaped words, default values and env values
59	    // never are.
60	    let mut explicit_opts = HashSet::<Id>::new();
61	    while let Some(arg) = raw_args.next(&mut cursor) {
62	        let current_state = next_state;
63	        next_state = ParseState::ValueDone;
64	        debug!(
65	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
66	            arg.to_value_os(),
67	        );
68	        if cursor == target_cursor {
69	            if is_illegal {
70	                return Err(std::io::Error::other("no completion generated"));
71	            }
72	            // A terminator typed immediately after the standalone terminator
73	            // would be a second one; it closes no value and cannot complete.
74	            if last_terminator
75	                .as_deref()
76	                .is_some_and(|term| word_is(term, &arg))
77	            {
78	                return Err(std::io::Error::other("no completion generated"));
79	            }
80	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
81	            return complete_arg(
82	                &arg,
83	                current_cmd,
84	                current_dir,
85	                pos_index,
86	                is_escaped,
87	                current_state,
88	                &disabled,
89	            );
90	        }
91	
92	        // The terminator that ended the previous closed word, repeated here,
93	        // cannot close the occurrence a second time.
94	        let duplicate_terminator = last_terminator
95	            .as_deref()
96	            .is_some_and(|term| word_is(term, &arg));
97	        if duplicate_terminator {
98	            is_illegal = true;
99	        }
100	
101	        if let Ok(value) = arg.to_value() {
102	            // A dangling delimiter forces this word to be the option's next
103	            // segment, never a subcommand.
104	            let open_segment = matches!(&current_state, ParseState::Opt(state) if state.open);
105	            if !open_segment {
106	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
107	                    current_cmd = next_cmd;
108	                    pos_index = 1;
109	                    last_terminator = None;
110	                    continue;
111	                }
112	            }
113	        }
114	
115	        // A standalone terminator word ends the option's value taking; it is
116	        // neither a value nor a candidate. It cannot arrive while a dangling
117	        // delimiter still expects a segment, before the option's minimum number
118	        // of value words is present, or after an earlier illegal word.
119	        let mut consumed_terminator: Option<OsString> = None;
120	        if let ParseState::Opt(state) = &current_state {
121	            if let Some(terminator) = state.opt.get_value_terminator() {
122	                if word_is(OsStr::new(terminator.as_str()), &arg) {
123	                    let min = state.opt.get_num_args().expect("built").min_values();
124	                    let consumed_words = state.word.saturating_sub(1);
125	                    if state.open || consumed_words < min || is_illegal {
126	                        is_illegal = true;
127	                    } else {
128	                        consumed_terminator = Some(OsString::from(terminator.as_str()));
129	                    }
130	                }
131	            }
132	        }
133	
134	        // While a dangling delimiter makes the next segment mandatory
135	        // (`--opt=a,`), a closed word may only be that segment.  An option
136	        // word (recognized or not) or `--` cannot fill it and clap rejects the
137	        // line, so completion reports an error instead of guessing a stop or a
138	        // new option. An option with `allow_hyphen_values` still accepts a
139	        // hyphen-prefixed word as the segment. A plain value word below is
140	        // consumed as the segment.
141	        if let ParseState::Opt(state) = &current_state {
142	            if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
143	                let is_option_word = arg.is_escape()
144	                    || arg.to_long().is_some()
145	                    || arg
146	                        .to_short()
147	                        .is_some_and(|short| !short.is_negative_number());
148	                if is_option_word {
149	                    is_illegal = true;
150	                }
151	            }
152	        }
153	
154	        // Once the value occurrence is complete, only the standalone terminator
155	        // still belongs to it; any other word resumes ordinary option/positional
156	        // parsing. This one-word window makes the terminator work identically
157	        // across `=`, separate words, shorts and aliases.
158	        let dispatch_state = if matches!(&current_state, ParseState::Opt(state) if state.closed)
159	            && consumed_terminator.is_none()
160	        {
161	            ParseState::ValueDone
162	        } else {
163	            current_state
164	        };
165	
166	        if is_escaped {
167	            (next_state, pos_index) =
168	                parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
169	        } else if arg.is_escape() {
170	            is_escaped = true;
171	        } else if consumed_terminator.is_some() {
172	            next_state = ParseState::ValueDone;
173	        } else if opt_allows_hyphen(&dispatch_state, &arg) {
174	            match dispatch_state {
175	                ParseState::Opt(state) => {
176	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
177	                }
178	                _ => unreachable!("else branch is only reachable in Opt state"),
179	            }
180	        } else if let Some((flag, value)) = arg.to_long() {
181	            if let Ok(flag) = flag {
182	                let opt = current_cmd.get_arguments().find(|a| {
183	                    let longs = a.get_long_and_visible_aliases();
184	                    let is_find = longs.map(|v| {
185	                        let mut iter = v.into_iter();
186	                        let s = iter.find(|s| *s == flag);
187	                        s.is_some()
188	                    });
189	                    is_find.unwrap_or(false)
190	                });
191	
192	                if let Some(opt) = opt {
193	                    explicit_opts.insert(opt.get_id().clone());
194	                    if opt.get_num_args().expect("built").takes_values() {
195	                        match value {
196	                            // A bare `--name` still expects its value as the next word.
197	                            None => next_state = ParseState::Opt(OptState::new(opt, 1)),
198	                            // A closed `--name=value` word normally ends the
199	                            // occurrence, but a dangling value delimiter with
200	                            // room for another segment keeps accepting values.
201	                            Some(value) => {
202	                                next_state = attached_opt_state(opt, value, &mut is_illegal);
203	                            }
204	                        }
205	                    }
206	                } else if pos_allows_hyphen(current_cmd, pos_index) {
207	                    (next_state, pos_index) =
208	                        parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
209	                }
210	            }
211	        } else if let Some(short) = arg.to_short() {
212	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
213	                parse_shortflags(current_cmd, short);
214	            // Only a cluster made entirely of recognized flags records state.
215	            // Splitting an invalid short string into known and unknown members
216	            // would be guesswork and could suppress conflicting candidates, so
217	            // invalid clusters keep the existing completion behavior; clap's
218	            // parser would reject them anyway.
219	            if cluster_valid {
220	                // Every recognized flag in the cluster was explicitly supplied.
221	                for flag in leading_flags.chars() {
222	                    if let Some(opt) = current_cmd.get_arguments().find(|a| {
223	                        a.get_short_and_visible_aliases()
224	                            .is_some_and(|shorts| shorts.contains(&flag))
225	                    }) {
226	                        explicit_opts.insert(opt.get_id().clone());
227	                    }
228	                }
229	            }
230	            if let Some(opt) = takes_value_opt {
231	                if let Some(remainder) = short.next_value_os() {
232	                    // A closed `-ovalue` / `-o=value` word; advance like the
233	                    // long `--opt=value` form.
234	                    let value = remainder.strip_prefix("=").unwrap_or(remainder);
235	                    next_state = attached_opt_state(opt, value, &mut is_illegal);
236	                } else {
237	                    next_state = ParseState::Opt(OptState::new(opt, 1));
238	                }
239	            } else if pos_allows_hyphen(current_cmd, pos_index) {
240	                (next_state, pos_index) =
241	                    parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
242	            }
243	        } else {
244	            match dispatch_state {
245	                ParseState::ValueDone | ParseState::Pos(..) => {
246	                    (next_state, pos_index) =
247	                        parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
248	                }
249	                ParseState::Opt(state) => {
250	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
251	                }
252	            }
253	        }
254	
255	        // Remember a just-consumed terminator for exactly one word so a
256	        // repeated terminator is flagged as a duplicate; every other word
257	        // clears it and resumes ordinary parsing.
258	        last_terminator = consumed_terminator;
259	    }
260	
261	    Err(std::io::Error::other("no completion generated"))
262	}
263	
264	#[derive(Debug, PartialEq, Eq, Clone)]
265	enum ParseState<'a> {
266	    /// Parsing a value done, there is no state to record.
267	    ValueDone,
268	
269	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
270	    Pos((usize, usize)),
271	
272	    /// Parsing a optional flag argument
273	    Opt(OptState<'a>),
274	}
275	
276	/// Ongoing state while an option still accepts value words.
277	#[derive(Debug, PartialEq, Eq, Clone)]
278	struct OptState<'a> {
279	    opt: &'a clap::Arg,
280	    /// Ordinal of the value word about to be consumed within this occurrence.
281	    /// A bare `--name` waiting for its first value starts at `1`; this is the
282	    /// value handed to [`ArgValueCompleter::complete_at`] as `arg_index + 1`,
283	    /// so it counts shell words and is unaffected by the value delimiter.
284	    word: usize,
285	    /// Delimiter segments already closed by earlier value words, in order.
286	    used: Vec<OsString>,
287	    /// The state was reached through a dangling value delimiter, so the next
288	    /// word is another segment of this option rather than an optional stop.
289	    open: bool,
290	    /// The value occurrence itself is complete (an attached word or a full
291	    /// delimiter set), so ordinary parsing resumes, but the option's standalone
292	    /// terminator may still arrive as the very next word. This makes the
293	    /// terminator work identically whether values arrived through `=`, a
294	    /// separate word, a short flag or an alias.
295	    closed: bool,
296	}
297	
298	impl<'a> OptState<'a> {
299	    fn new(opt: &'a clap::Arg, word: usize) -> Self {
300	        Self {
301	            opt,
302	            word,
303	            used: Vec::new(),
304	            open: false,
305	            closed: false,
306	        }
307	    }
308	}
309	
310	/// Whether an option carries several values split by a delimiter inside one
311	/// shell word *and* bounds how many such values it accepts.
312	///
313	/// An argument with the default range of one value may still pack an arbitrary
314	/// number of delimiter segments into its single word (clap's parser allows it),
315	/// and completion preserves that legacy behavior; only multi-value arguments
316	/// count segments against their range.
317	fn is_bounded_delimited(opt: &clap::Arg) -> Option<char> {
318	    let delim = opt.get_value_delimiter()?;
319	    if opt.get_num_args().expect("built").max_values() > 1 {
320	        Some(delim)
321	    } else {
322	        None
323	    }
324	}
325	
326	/// Whether a terminator glued into a value word is structurally impossible for
327	/// this option. clap rejects such a word when the option packs a bounded,
328	/// delimiter-separated set from fixed possible values (a segment like `;x` can
329	/// never name a value), while a free-form option simply takes the whole word.
330	fn glued_terminator_is_illegal(opt: &clap::Arg) -> bool {
331	    is_bounded_delimited(opt).is_some() && possible_values(opt).is_some()
332	}
333	
334	/// Split a shell value on its delimiter into its closed segments.
335	///
336	/// Returns `(segments, dangling)` where `dangling` is set when the value ends
337	/// with the delimiter: the final empty piece is the segment still being typed
338	/// rather than a closed (empty and therefore invalid) segment. Splitting works
339	/// on raw [`OsStr`] bytes, so invalid UTF-8 values are handled too.
340	fn split_delimited(value: &OsStr, delim: char) -> (Vec<&OsStr>, bool) {
341	    let mut buf = [0_u8; 4];
342	    let delim_str = delim.encode_utf8(&mut buf);
343	    let mut segments: Vec<&OsStr> = value.split(delim_str).collect();
344	    let dangling = value.contains(delim_str) && segments.last().is_some_and(|last| last.is_empty());
345	    if dangling {
346	        segments.pop();
347	    }
348	    (segments, dangling)
349	}
350	
351	/// Fold one closed value word into an option's ongoing value state.
352	///
353	/// `Ok(None)` means the occurrence is complete, `Ok(Some(state))` that another
354	/// value word is accepted and `Err(())` that the word cannot be part of a valid
355	/// command line (an empty delimiter segment or more segments than the option
356	/// accepts); the latter produces "no completion generated" rather than guesses.
357	fn consume_opt_word<'a>(
358	    prior: OptState<'a>,
359	    value: &OsStr,
360	    attached: bool,
361	) -> Result<Option<OptState<'a>>, ()> {
362	    let opt = prior.opt;
363	    let range = opt.get_num_args().expect("built");
364	    let max = range.max_values();
365	    let ordinal = prior.word;
366	    let mut used = prior.used;
367	
368	    let Some(delim) = is_bounded_delimited(opt) else {
369	        // Legacy behavior: count whole shell words against the range; whatever
370	        // is packed behind a delimiter does not extend or shorten the count.
371	        // An attached value always closes the occurrence.
372	        return Ok(if !attached && ordinal < max {
373	            Some(OptState {
374	                opt,
375	                word: ordinal + 1,
376	                used,
377	                open: false,
378	                closed: false,
379	            })
380	        } else {
381	            None
382	        });
383	    };
384	
385	    let mut buf = [0_u8; 4];
386	    let delim_str = delim.encode_utf8(&mut buf);
387	    let (segments, dangling) = split_delimited(value, delim);
388	    // Empty pieces are only invalid once a delimiter actually separates
389	    // segments; a bare empty value (`--opt=`) keeps its old tolerant behavior.
390	    if value.contains(delim_str) && segments.iter().any(|s| s.is_empty()) {
391	        return Err(());
392	    }
393	    // A closed segment must name a value the option accepts; an unknown value
394	    // cannot be part of a valid command line.
395	    if !segments_are_known(opt, &segments) {
396	        return Err(());
397	    }
398	    let closed = used.len() + segments.len();
399	    if closed > max || (closed == max && dangling) {
400	        return Err(());
401	    }
402	    used.extend(segments.iter().map(|s| s.to_os_string()));
403	
404	    // An attached value closes the occurrence unless a dangling delimiter
405	    // still accepts another segment; a space-separated word keeps accepting
406	    // values until the range is full.
407	    let accepts_more = dangling || (!attached && closed < max);
408	    if accepts_more {
409	        Ok(Some(OptState {
410	            opt,
411	            word: ordinal + 1,
412	            used,
413	            open: dangling,
414	            closed: false,
415	        }))
416	    } else if opt.get_value_terminator().is_some() {
417	        // The value occurrence is complete, but an argument with a value
418	        // terminator still accepts the standalone terminator as the very next
419	        // word, no matter whether the values arrived through `=`, a separate
420	        // word, a short flag or an alias. Keep a one-word "closed" window so
421	        // every spelling reaches the same explicit end state.
422	        Ok(Some(OptState {
423	            opt,
424	            word: ordinal + 1,
425	            used,
426	            open: false,
427	            closed: true,
428	        }))
429	    } else {
430	        Ok(None)
431	    }
432	}
433	
434	/// State after a closed `--opt=value` word: `ValueDone` when the occurrence is
435	/// complete, `Opt` when a dangling delimiter still accepts another segment.
436	/// Illegal values flag the whole command line as uncompletable.
437	fn attached_opt_state<'a>(
438	    opt: &'a clap::Arg,
439	    value: &OsStr,
440	    is_illegal: &mut bool,
441	) -> ParseState<'a> {
442	    match consume_opt_word(OptState::new(opt, 1), value, true) {
443	        Ok(Some(state)) => ParseState::Opt(state),
444	        Ok(None) => ParseState::ValueDone,
445	        Err(()) => {
446	            *is_illegal = true;
447	            ParseState::ValueDone
448	        }
449	    }
450	}
451	
452	/// Advance an ongoing option occurrence by one space-separated value word.
453	fn advance_opt_value<'a>(
454	    state: OptState<'a>,
455	    value: &OsStr,
456	    is_illegal: &mut bool,
457	) -> ParseState<'a> {
458	    match consume_opt_word(state, value, false) {
459	        Ok(Some(next)) => ParseState::Opt(next),
460	        Ok(None) => ParseState::ValueDone,
461	        Err(()) => {
462	            *is_illegal = true;
463	            ParseState::ValueDone
464	        }
465	    }
466	}
467	
468	/// Whether the whole shell word is exactly the given terminator.
469	fn word_is(terminator: &OsStr, arg: &clap_lex::ParsedArg<'_>) -> bool {
470	    arg.to_value_os() == terminator
471	}
472	
473	/// Result of analyzing the value word under the cursor for an option that
474	/// packs delimiter-separated values.
475	struct DelimCursor<'s> {
476	    /// Text of the segment currently being typed.
477	    current: &'s OsStr,
478	    /// Closed segments that precede it, in order.
479	    closed: Vec<&'s OsStr>,
480	    /// Everything in this shell word before the current segment, including the
481	    /// trailing delimiter, to re-prefix candidates with.
482	    prefix: &'s str,
483	}
484	
485	/// Whether every closed delimiter segment names a value the option accepts.
486	///
487	/// Options without a fixed value set accept anything.  A bare empty value
488	/// (`--opt=`) keeps its legacy tolerant treatment; empty segments separated
489	/// by a delimiter are rejected before this point.  A segment that is not
490	/// valid UTF-8 cannot match a possible value and is rejected, as clap's
491	/// parser would reject it.
492	fn segments_are_known(opt: &clap::Arg, segments: &[&OsStr]) -> bool {
493	    let Some(possible) = possible_values(opt) else {
494	        return true;
495	    };
496	    let ignore_case = opt.is_ignore_case_set();
497	    let possible: Vec<_> = possible.collect();
498	    segments.iter().all(|segment| {
499	        segment
500	            .to_str()
501	            .is_some_and(|s| s.is_empty() || possible.iter().any(|pv| pv.matches(s, ignore_case)))
502	    })
503	}
504	
505	/// Split the cursor value of a bounded delimiter option into the segment being
506	/// edited and its already closed prefix segments.
507	///
508	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
509	/// completion applies); `Err(())` means the cursor sits at an illegal segment
510	/// position (a leading/empty segment or one past the accepted number of
511	/// values), which must not produce candidates.
512	fn cursor_delimited<'s>(
513	    opt: &clap::Arg,
514	    value: &'s OsStr,
515	    prior_segments: usize,
516	) -> Result<Option<DelimCursor<'s>>, ()> {
517	    let Some(delim) = is_bounded_delimited(opt) else {
518	        return Ok(None);
519	    };
520	    let max = opt.get_num_args().expect("built").max_values();
521	    // The cursor word being edited keeps the legacy whole-word completion when
522	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
523	    let value_str = match value.to_str() {
524	        Some(s) => s,
525	        None => return Ok(None),
526	    };
527	    let mut buf = [0_u8; 4];
528	    let delim_str = delim.encode_utf8(&mut buf);
529	
530	    let Some(pos) = value_str.rfind(delim) else {
531	        return Ok(Some(DelimCursor {
532	            current: value,
533	            closed: Vec::new(),
534	            prefix: "",
535	        }));
536	    };
537	    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
538	    let closed: Vec<&OsStr> = prefix[..prefix.len() - delim_str.len()]
539	        .split(delim)
540	        .map(OsStr::new)
541	        .collect();
542	    if closed.iter().any(|s| s.is_empty())
543	        || prior_segments + closed.len() >= max
544	        || !segments_are_known(opt, &closed)
545	    {
546	        return Err(());
547	    }
548	    Ok(Some(DelimCursor {
549	        current: OsStr::new(current),
550	        closed,
551	        prefix,
552	    }))
553	}
554	
555	fn complete_arg(
556	    arg: &clap_lex::ParsedArg<'_>,
557	    cmd: &clap::Command,
558	    current_dir: Option<&std::path::Path>,
559	    pos_index: usize,
560	    is_escaped: bool,
561	    state: ParseState<'_>,
562	    disabled: &HashSet<Id>,
563	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
564	    debug!(
565	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
566	        arg,
567	        cmd.get_name(),
568	        current_dir,
569	        pos_index,
570	        state
571	    );
572	    let mut completions = Vec::<CompletionCandidate>::new();
573	
574	    match state {
575	        ParseState::ValueDone => {
576	            // A closed `--name=value` word (or a short cluster carrying an
577	            // inline value, e.g. `-ovalue` / `-o=value`) is the option's value
578	            // position: only the option's own values are completed, exactly as
579	            // if the value had been written as a separate word.  The content
580	            // after `=` never takes part in subcommand, positional or
581	            // option-name completion, and the word itself is not yet part of
582	            // the conflict set.
583	            if !is_escaped {
584	                if let Some(values) = complete_inline_option_value(arg, cmd, current_dir, disabled)
585	                {
586	                    let values =
587	                        values.map_err(|()| std::io::Error::other("no completion generated"))?;
588	                    completions.extend(values);
589	                    return finalize_completions(completions);
590	                }
591	            }
592	
593	            // After `--`, only positional arguments are completed.
594	            if !is_escaped {
595	                if let Ok(value) = arg.to_value() {
596	                    completions.extend(complete_subcommand(value, cmd));
597	                }
598	            }
599	
600	            if let Some(positional) = cmd
601	                .get_positionals()
602	                .find(|p| p.get_index() == Some(pos_index))
603	            {
604	                if !disabled.contains(positional.get_id()) {
605	                    completions.extend(complete_arg_value(
606	                        arg.to_value(),
607	                        positional,
608	                        current_dir,
609	                        0,
610	                    ));
611	                }
612	            }
613	            if !is_escaped {
614	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
615	            }
616	        }
617	        ParseState::Pos((_, num_arg)) => {
618	            if let Some(positional) = cmd
619	                .get_positionals()
620	                .find(|p| p.get_index() == Some(pos_index))
621	            {
622	                if !disabled.contains(positional.get_id()) {
623	                    completions.extend(complete_arg_value(
624	                        arg.to_value(),
625	                        positional,
626	                        current_dir,
627	                        num_arg.saturating_sub(1),
628	                    ));
629	                }
630	                if !is_escaped
631	                    && positional
632	                        .get_num_args()
633	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
634	                {
635	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
636	                }
637	            }
638	        }
639	        ParseState::Opt(state) => {
640	            let opt = state.opt;
641	            // A value terminator is only ever its own whole word for a bounded
642	            // delimited option.
643	            if let Some(terminator) = opt.get_value_terminator() {
644	                let min = opt.get_num_args().expect("built").min_values();
645	                let consumed_words = state.word.saturating_sub(1);
646	                let word = arg.to_value_os();
647	                let term = OsStr::new(terminator.as_str());
648	                let is_exact = word == term;
649	                let is_glued = !is_exact && word.contains(terminator.as_str());
650	                if is_glued && glued_terminator_is_illegal(opt) {
651	                    // A terminator glued onto a segment of a bounded, fixed-set
652	                    // delimiter option cannot be a value; the engine never
653	                    // guesses a split into value plus terminator. A free-form
654	                    // option takes the whole word instead.
655	                    return Err(std::io::Error::other("no completion generated"));
656	                }
657	                if is_exact {
658	                    if state.open || consumed_words < min {
659	                        // A dangling delimiter still owes its segment and the
660	                        // option still owes its minimum number of value words.
661	                        return Err(std::io::Error::other("no completion generated"));
662	                    }
663	                    // The terminator closes value taking and is never itself a
664	                    // candidate.
665	                    return finalize_completions(completions);
666	                }
667	                if state.closed {
668	                    // The value occurrence already closed (`--opt=value` or a
669	                    // full delimiter set); only the terminator word still
670	                    // belongs to it. Complete ordinary options/positionals.
671	                    return complete_arg(
672	                        arg,
673	                        cmd,
674	                        current_dir,
675	                        pos_index,
676	                        is_escaped,
677	                        ParseState::ValueDone,
678	                        disabled,
679	                    );
680	                }
681	            }
682	            if !disabled.contains(opt.get_id()) {
683	                match complete_separate_opt_value(arg.to_value(), &state, current_dir) {
684	                    Ok(values) => completions.extend(values),
685	                    // The cursor sits at an illegal segment position (an empty
686	                    // segment or one past the accepted number of values).
687	                    Err(()) => return Err(std::io::Error::other("no completion generated")),
688	                }
689	            }
690	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
691	            if state.word > min && !state.open {
692	                // Also complete this raw_arg as a positional argument, flags,
693	                // options and subcommand.  A dangling delimiter (`state.open`)
694	                // requires the next word to be this option's segment: it cannot
695	                // be a valid stop, so nothing else is offered there.
696	                completions.extend(complete_arg(
697	                    arg,
698	                    cmd,
699	                    current_dir,
700	                    pos_index,
701	                    is_escaped,
702	                    ParseState::ValueDone,
703	                    disabled,
704	                )?);
705	            }
706	        }
707	    }
708	
709	    finalize_completions(completions)
710	}
