712	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
713	/// into the presentation order shared by every completion source.
714	fn finalize_completions(
715	    mut completions: Vec<CompletionCandidate>,
716	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
717	    if completions.iter().any(|a| !a.is_hide_set()) {
718	        completions.retain(|a| !a.is_hide_set());
719	    }
720	    let mut seen_ids = HashSet::new();
721	    completions.retain(move |a| {
722	        if let Some(id) = a.get_id().cloned() {
723	            seen_ids.insert(id)
724	        } else {
725	            true
726	        }
727	    });
728	    // Different sources (a subcommand and a positional value, an option alias
729	    // and a directory entry, ...) can propose the same literal insertion text
730	    // under different ids; only the first is kept.  Retaining by first
731	    // occurrence keeps the presentation order untouched by aliases or
732	    // duplicate directory entries.
733	    let mut seen_values = HashSet::new();
734	    completions.retain(move |a| seen_values.insert(a.get_value().to_os_string()));
735	
736	    let mut tags = Vec::new();
737	    for candidate in &completions {
738	        let tag = candidate.get_tag().cloned();
739	        if !tags.contains(&tag) {
740	            tags.push(tag);
741	        }
742	    }
743	    completions.sort_by_key(|c| {
744	        (
745	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
746	            c.get_display_order(),
747	        )
748	    });
749	
750	    Ok(completions)
751	}
