753	/// Generate value candidates for the segment under the cursor of a
754	/// delimiter-separated multi-value option.
755	///
756	/// `prior_segments` is the number of segments already closed by earlier shell
757	/// words; `prior_used` are their literal values, suppressed from the result so
758	/// an already selected value is not offered a second time.  Candidates cover
759	/// only the current shell word, so `prefix` from closed segments is limited to
760	/// the current word as well.
761	///
762	/// `Ok` carries the candidates; `Err(())` marks an illegal segment position
763	/// (an empty segment or a segment past the accepted number of values).
764	fn complete_segment_value(
765	    value: &OsStr,
766	    opt: &clap::Arg,
767	    prior_segments: usize,
768	    prior_used: &[&OsStr],
769	    arg_index: usize,
770	    current_dir: Option<&std::path::Path>,
771	) -> Result<Vec<CompletionCandidate>, ()> {
772	    // For a bounded delimiter option with a fixed value set, the terminator is
773	    // recognized only as a standalone word; glued onto a segment (`--opt=a;`,
774	    // `--opt=;`) it cannot be part of a valid line and the engine never guesses
775	    // a split. A free-form option takes the whole word, like clap's parser.
776	    if glued_terminator_is_illegal(opt) {
777	        if let Some(terminator) = opt.get_value_terminator() {
778	            if value.contains(terminator.as_str()) {
779	                return Err(());
780	            }
781	        }
782	    }
783	    let Some(cursor) = cursor_delimited(opt, value, prior_segments)? else {
784	        // Not a bounded delimiter option: keep the legacy whole-word
785	        // completion (its own `rsplit_delimiter` handles single-value args).
786	        return Ok(complete_arg_value(
787	            value.to_str().ok_or(value),
788	            opt,
789	            current_dir,
790	            arg_index,
791	        ));
792	    };
793	
794	    let mut used: Vec<&OsStr> = prior_used.to_vec();
795	    used.extend(cursor.closed.iter().copied());
796	
797	    let mut values = complete_arg_value(
798	        Ok(cursor.current.to_str().ok_or(())?),
799	        opt,
800	        current_dir,
801	        arg_index,
802	    );
803	    // An already closed segment stays selected and must not reappear.
804	    values.retain(|comp| !used.iter().any(|u| *u == comp.get_value()));
805	    if !cursor.prefix.is_empty() {
806	        values = values
807	            .into_iter()
808	            .map(|comp| comp.add_prefix(cursor.prefix))
809	            .collect();
810	    }
811	    Ok(values)
812	}
