814	/// Completion at a space-separated option value word tracked by `state`.
815	fn complete_separate_opt_value(
816	    value: Result<&str, &OsStr>,
817	    state: &OptState<'_>,
818	    current_dir: Option<&std::path::Path>,
819	) -> Result<Vec<CompletionCandidate>, ()> {
820	    let value_os = match value {
821	        Ok(value) => OsStr::new(value),
822	        Err(value_os) => value_os,
823	    };
824	    let used: Vec<&OsStr> = state.used.iter().map(OsString::as_os_str).collect();
825	    complete_segment_value(
826	        value_os,
827	        state.opt,
828	        state.used.len(),
829	        &used,
830	        state.word.saturating_sub(1),
831	        current_dir,
832	    )
833	}
