835	/// Complete the inline value carried by the cursor's option word.
836	///
837	/// This covers `--name=value` as well as short clusters with an attached
838	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
839	/// It returns the option's value candidates, re-prefixed with the exact
840	/// option spelling, when the cursor is inside such a value.  The whole word is
841	/// consumed by its option: nothing after `=` or past the taking flag takes
842	/// part in option-name, subcommand or positional completion, and the word is
843	/// not yet part of the conflict set.
844	///
845	/// A bare `--name`/`-o` whose value is still a separate word completes
846	/// normally, as does an unknown long name, a recognized option that takes no
847	/// value and anything else that cannot be recognized: `None` preserves the
848	/// existing failure semantics rather than guessing a split.
849	///
850	/// `Some(Err(()))` means the recognized word is an illegal value position for
851	/// a bounded delimiter option (an empty segment or a segment past the accepted
852	/// number of values) and must yield "no completion generated".
853	fn complete_inline_option_value(
854	    arg: &clap_lex::ParsedArg<'_>,
855	    cmd: &clap::Command,
856	    current_dir: Option<&std::path::Path>,
857	    disabled: &HashSet<Id>,
858	) -> Option<Result<Vec<CompletionCandidate>, ()>> {
859	    if let Some((flag, value)) = arg.to_long() {
860	        let flag = flag.ok()?;
861	        // A bare `--name` has no attached value and is completed as an option name.
862	        let value = value?;
863	        let opt = cmd.get_arguments().find(|a| {
864	            a.get_long_and_visible_aliases()
865	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
866	        })?;
867	        if !opt.get_num_args().expect("built").takes_values() {
868	            return None;
869	        }
870	        if disabled.contains(opt.get_id()) {
871	            return Some(Ok(Vec::new()));
872	        }
873	        let prefix = format!("--{flag}=");
874	        return Some(
875	            complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
876	                values
877	                    .into_iter()
878	                    .map(|comp| comp.add_prefix(&prefix))
879	                    .collect()
880	            }),
881	        );
882	    }
883	
884	    let short = arg.to_short()?;
885	    if short.is_negative_number() {
886	        return None;
887	    }
888	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
889	    let opt = opt?;
890	
891	    // Detect an attached value: once the cluster reaches its value-taking
892	    // flag, everything left is the value, optionally introduced by `=`.  With
893	    // no remainder and no `=` (`-o`), the word is left to the regular option
894	    // completion, which already offers inline values.
895	    let mut peek = value_flags.clone();
896	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
897	    if !has_equal && value_flags.is_empty() {
898	        return None;
899	    }
900	    if has_equal {
901	        // Consume the `=` so the remainder is the bare value (possibly empty
902	        // for `-o=`), matching the space-separated empty-value position.
903	        value_flags.next_flag();
904	    }
905	    if disabled.contains(opt.get_id()) {
906	        return Some(Ok(Vec::new()));
907	    }
908	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
909	    let sep = if has_equal { "=" } else { "" };
910	    let prefix = format!("-{leading_flags}{sep}");
911	    Some(
912	        complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
913	            values
914	                .into_iter()
915	                .map(|comp| comp.add_prefix(&prefix))
916	                .collect()
917	        }),
918	    )
919	}
