921	fn complete_option(
922	    arg: &clap_lex::ParsedArg<'_>,
923	    cmd: &clap::Command,
924	    current_dir: Option<&std::path::Path>,
925	    disabled: &HashSet<Id>,
926	) -> Vec<CompletionCandidate> {
927	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
928	    let mut completions = Vec::<CompletionCandidate>::new();
929	    if arg.is_empty() {
930	        completions.extend(longs_and_visible_aliases(cmd, disabled));
931	        completions.extend(hidden_longs_aliases(cmd, disabled));
932	
933	        let dash_or_arg = if arg.is_empty() {
934	            "-".into()
935	        } else {
936	            arg.to_value_os().to_string_lossy()
937	        };
938	        completions.extend(
939	            shorts_and_visible_aliases(cmd, disabled)
940	                .into_iter()
941	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
942	        );
943	    } else if arg.is_stdio() {
944	        // HACK: Assuming knowledge of is_stdio
945	        let dash_or_arg = if arg.is_empty() {
946	            "-".into()
947	        } else {
948	            arg.to_value_os().to_string_lossy()
949	        };
950	        completions.extend(
951	            shorts_and_visible_aliases(cmd, disabled)
952	                .into_iter()
953	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
954	        );
955	
956	        completions.extend(longs_and_visible_aliases(cmd, disabled));
957	        completions.extend(hidden_longs_aliases(cmd, disabled));
958	    } else if arg.is_escape() {
959	        // HACK: Assuming knowledge of is_escape
960	        completions.extend(longs_and_visible_aliases(cmd, disabled));
961	        completions.extend(hidden_longs_aliases(cmd, disabled));
962	    } else if let Some((flag, value)) = arg.to_long() {
963	        if let Ok(flag) = flag {
964	            if let Some(value) = value {
965	                let opt = cmd.get_arguments().find(|a| {
966	                    a.get_long_and_visible_aliases()
967	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
968	                });
969	                if let Some(arg) = opt {
970	                    if !disabled.contains(arg.get_id()) {
971	                        if let Ok(values) =
972	                            complete_segment_value(value, arg, 0, &[], 0, current_dir)
973	                        {
974	                            completions.extend(
975	                                values
976	                                    .into_iter()
977	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
978	                            );
979	                        }
980	                    }
981	                }
982	            } else {
983	                completions.extend(
984	                    longs_and_visible_aliases(cmd, disabled)
985	                        .into_iter()
986	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
987	                );
988	                completions.extend(
989	                    hidden_longs_aliases(cmd, disabled)
990	                        .into_iter()
991	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
992	                );
993	            }
994	        }
995	    } else if let Some(short) = arg.to_short() {
996	        if !short.is_negative_number() {
997	            // Find the first takes_values option.
998	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
999	
1000	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
1001	            if let Some(opt) = takes_value_opt {
1002	                if !disabled.contains(opt.get_id()) {
1003	                    let mut peek_short = short.clone();
1004	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
1005	                        short.next_flag();
1006	                        true
1007	                    } else {
1008	                        false
1009	                    };
1010	
1011	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
1012	                    if let Ok(values) = complete_segment_value(value, opt, 0, &[], 0, current_dir) {
1013	                        completions.extend(values.into_iter().map(|comp| {
1014	                            let sep = if has_equal { "=" } else { "" };
1015	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
1016	                        }));
1017	                    }
1018	                }
1019	            } else {
1020	                completions.extend(
1021	                    shorts_and_visible_aliases(cmd, disabled)
1022	                        .into_iter()
1023	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
1024	                );
1025	            }
1026	        }
1027	    }
1028	    debug!("complete_option: completions={completions:?}");
1029	    completions
1030	}
