1120	fn rsplit_delimiter<'s, 'o>(
1121	    value: Result<&'s str, &'o OsStr>,
1122	    delimiter: Option<char>,
1123	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
1124	    let delimiter = delimiter?;
1125	    let value = value.ok()?;
1126	    let pos = value.rfind(delimiter)?;
1127	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
1128	    Some((Some(prefix), Ok(value)))
1129	}
