1161	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
1162	    debug!(
1163	        "complete_subcommand: cmd={:?}, value={:?}",
1164	        cmd.get_name(),
1165	        value
1166	    );
1167	
1168	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
1169	        .into_iter()
1170	        .filter(|x| x.get_value().starts_with(value))
1171	        .collect();
1172	    if cmd.is_allow_external_subcommands_set() {
