1313	/// Parse the short flags and find the first `takes_values` option.
1314	///
1315	/// The returned bool is `true` only when every scanned cluster member was a
1316	/// recognized option. Anything after the first value-taking option is the
1317	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1318	/// characters make the result `false`.
1319	fn parse_shortflags<'c, 's>(
1320	    cmd: &'c clap::Command,
1321	    mut short: clap_lex::ShortFlags<'s>,
1322	) -> (
1323	    String,
1324	    Option<&'c clap::Arg>,
1325	    clap_lex::ShortFlags<'s>,
1326	    bool,
1327	) {
1328	    let takes_value_opt;
1329	    let mut leading_flags = String::new();
1330	    let mut cluster_valid = true;
1331	    // Find the first takes_values option.
1332	    loop {
1333	        match short.next_flag() {
1334	            Some(Ok(opt)) => {
1335	                leading_flags.push(opt);
1336	                let found = cmd.get_arguments().find(|a| {
1337	                    let shorts = a.get_short_and_visible_aliases();
1338	                    let is_find = shorts.map(|v| {
1339	                        let mut iter = v.into_iter();
1340	                        let c = iter.find(|c| *c == opt);
1341	                        c.is_some()
1342	                    });
1343	                    is_find.unwrap_or(false)
1344	                });
1345	                if let Some(opt) = found {
1346	                    if opt.get_num_args().expect("built").takes_values() {
1347	                        takes_value_opt = Some(opt);
1348	                        break;
1349	                    }
1350	                } else {
1351	                    cluster_valid = false;
1352	                }
1353	            }
1354	            Some(Err(_)) => {
1355	                cluster_valid = false;
1356	                takes_value_opt = None;
1357	                break;
1358	            }
1359	            None => {
1360	                takes_value_opt = None;
1361	                break;
1362	            }
1363	        }
1364	    }
1365	
1366	    (leading_flags, takes_value_opt, short, cluster_valid)
1367	}
1368	
1369	/// Parse the positional arguments. Return the new state and the new positional index.
1370	fn parse_positional<'a>(
1371	    cmd: &clap::Command,
1372	    pos_index: usize,
1373	    is_escaped: bool,
1374	    state: ParseState<'a>,
1375	) -> (ParseState<'a>, usize) {
1376	    let pos_arg = cmd
1377	        .get_positionals()
1378	        .find(|p| p.get_index() == Some(pos_index));
1379	    let num_args = pos_arg
1380	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1381	        .unwrap_or(1);
1382	
1383	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1384	        if num_args > 1 {
1385	            (ParseState::Pos((pos_index, 1)), pos_index)
1386	        } else {
1387	            if is_escaped {
1388	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1389	            } else {
1390	                (ParseState::ValueDone, pos_index + 1)
1391	            }
1392	        }
1393	    };
1394	    match state {
1395	        ParseState::ValueDone => {
1396	            update_state_with_new_positional(pos_index)
1397	        },
1398	        ParseState::Pos((prev_pos_index, num_arg)) => {
1399	            if prev_pos_index == pos_index {
1400	                if num_arg + 1 < num_args {
1401	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1402	                } else {
1403	                    if is_escaped {
1404	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1405	                    } else {
1406	                        (ParseState::ValueDone, pos_index + 1)
1407	                    }
1408	                }
1409	            } else {
1410	                update_state_with_new_positional(pos_index)
1411	            }
1412	        }
1413	        ParseState::Opt(..) => unreachable!(
1414	            "This branch won't be hit,
1415	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1416	        ),
1417	    }
1418	}
1419	
1420	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1421	    cmd.get_positionals()
1422	        .find(|a| a.get_index() == Some(pos_index))
1423	        .map(|p| p.is_allow_hyphen_values_set())
1424	        .unwrap_or(false)
1425	}
1426	
1427	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1428	    let val = arg.to_value_os();
1429	    if val.starts_with("-") {
1430	        if let ParseState::Opt(state) = state {
1431	            return state.opt.is_allow_hyphen_values_set();
1432	        }
1433	    }
1434	
1435	    false
1436	}
1437	
1438	/// Arguments that must not be offered because they conflict with an explicitly
1439	/// present option. The present options themselves are never disabled.
1440	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1441	    let mut disabled = HashSet::new();
1442	    if explicit.is_empty() {
1443	        return disabled;
1444	    }
1445	    for arg in cmd.get_arguments() {
1446	        if explicit.contains(arg.get_id()) {
1447	            // A present option hides everything it conflicts with ...
1448	            for id in arg_direct_conflicts(cmd, arg) {
1449	                if !explicit.contains(&id) {
1450	                    disabled.insert(id);
1451	                }
1452	            }
1453	        } else {
1454	            // ... and is hidden when either side declares the conflict.
1455	            if arg_direct_conflicts(cmd, arg)
1456	                .iter()
1457	                .any(|id| explicit.contains(id))
1458	            {
1459	                disabled.insert(arg.get_id().clone());
1460	            }
1461	        }
1462	    }
1463	    disabled
1464	}
1465	
1466	/// Conflict partners of `arg`, following the same rules as clap's parser:
1467	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1468	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1469	/// - the other members of non-`multiple` groups
1470	///
1471	/// Group ids are expanded to their argument members.
1472	/// `overrides_with` relationships are intentionally not considered.
1473	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1474	    let mut conflicts = arg
1475	        .get_conflicts_with()
1476	        .map(ToOwned::to_owned)
1477	        .collect::<HashSet<_>>();
1478	    for group in cmd.get_groups() {
1479	        let members = unroll_group(cmd, group.get_id());
1480	        if !members.iter().any(|m| m == arg.get_id()) {
1481	            continue;
1482	        }
1483	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1484	        if !group.is_multiple_set() {
1485	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1486	        }
1487	    }
1488	    conflicts
1489	        .iter()
1490	        .flat_map(|id| unroll_group(cmd, id))
1491	        .collect()
1492	}
1493	
1494	/// Resolve an argument or group id to its argument members.
1495	/// Unknown ids resolve to themselves.
1496	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1497	    let mut pending = vec![id.clone()];
1498	    let mut args = Vec::new();
1499	    while let Some(id) = pending.pop() {
1500	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1501	            if !args.contains(&id) {
1502	                args.push(id);
1503	            }
1504	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1505	            pending.extend(group.get_args().map(ToOwned::to_owned));
1506	        } else if !args.contains(&id) {
1507	            args.push(id);
1508	        }
1509	    }
1510	    args
1511	}
