#![cfg(feature = "unstable-dynamic")]

use clap::Command;
use clap_complete::engine::ArgValueCompleter;
use clap_complete::engine::CompletionCandidate;

fn terminator_command() -> Command {
    Command::new("tag")
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .visible_alias("label")
                .short('t')
                .num_args(1..=3)
                .value_parser(["red", "green", "blue"])
                .value_delimiter(',')
                .value_terminator(";"),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("tag"),
        )
        .arg(clap::Arg::new("path").value_parser(["src", "dst"]))
}

fn run(cmd: &mut Command, words: &[&str]) -> Result<Vec<String>, String> {
    let mut raw: Vec<std::ffi::OsString> = words.iter().map(std::ffi::OsString::from).collect();
    let arg_index = raw.len() - 1;
    let _ = &mut raw;
    clap_complete::engine::complete(cmd, raw, arg_index, None)
        .map(|cs| {
            cs.iter()
                .map(|c| c.get_value().to_string_lossy().into_owned())
                .collect()
        })
        .map_err(|e| e.to_string())
}

#[test]
fn probe_repeated_calls_same_command() {
    let mut cmd = terminator_command();

    // Same input completed twice on the same Command instance must give
    // identical results (no accumulated state, no mutated definition).
    let first = run(&mut cmd, &["tag", "--tag", "red", ";", ""]).unwrap();
    let second = run(&mut cmd, &["tag", "--tag", "red", ";", ""]).unwrap();
    assert_eq!(first, second);
    assert_eq!(first, vec!["src", "dst", "--tag", "--help"]);

    // A consumed terminator in an earlier call must not reopen value taking
    // in a later call, and an error result must not poison later calls.
    let err = run(&mut cmd, &["tag", "--tag", "red", ";", ";", ""]).unwrap_err();
    assert_eq!(err, "no completion generated");
    let third = run(&mut cmd, &["tag", "--tag", "red", ";", ""]).unwrap();
    assert_eq!(third, first);

    // Value completion still works after all of the above.
    let values = run(&mut cmd, &["tag", "--tag=red,", ""]).unwrap();
    assert_eq!(values, vec!["green", "blue"]);
}

